style.css:
@-moz-document domain("roblox.com") {
body, html {
    background-color: #121212 !important;
    color: #e0e0e0 !important;
  }

  a {
    color: #8ab4f8 !important;
  }

  /* Верхняя панель навигации */
  .navbar, .rbx-navbar, .nav-menu {
    background-color: #1f1f1f !important;
    color: #e0e0e0 !important;
  }

  /* Меню, карточки и элементы интерфейса */
  .section, .container-main, .content, .game-card, .tile, .dropdown-menu {
    background-color: #1e1e1e !important;
    color: #e0e0e0 !important;
  }

  /* Инпуты и кнопки */
  input, textarea, select, button {
    background-color: #2a2a2a !important;
    color: #ffffff !important;
    border: 1px solid #444 !important;
  }

  /* Изображения с белым фоном */
  img {
    background-color: transparent !important;
  }

  /* Удаление белых фонов */
  .ad, .ads-container, .banner-ad, .footer {
    background-color: #121212 !important;
  }

  /* Hover эффекты */
  .game-card:hover, .tile:hover {
    background-color: #292929 !important;
  }

  /* Специфические блоки */
  .game-name, .text-label, .text-overflow {
    color: #ffffff !important;
  }
}
